    @Test void returnFinalQuoteUsesActualInspectionWithoutFinancialReservation() throws Exception {
        var f=finalQuoteReturn("final-quote",true);var unit=f.accepted().units().getFirst();var before=returnApplicationParticipants();String path="/api/orders/"+f.parties().buyer().order().orderNumber()+"/returns/"+f.accepted().returnId()+"/quote";
        var response=accountRequest(f.parties().buyer().browser(),"POST",path,Map.of("expectedRevision",3),csrfToken(f.parties().buyer().browser()));assertEquals(200,response.statusCode(),"held inspected return needs an owner final quote: "+response.body());
        var body=authMapper.readTree(response.body());assertEquals(f.accepted().returnId().toString(),body.path("returnId").asText());assertEquals(3,body.path("returnRevision").asLong());var quote=body.path("feeQuote");assertEquals(1,quote.path("units").size());assertEquals("BUYER",quote.path("units").get(0).path("responsibility").asText());
        long net=jdbc.queryForObject("SELECT net FROM marketplace.order_unit WHERE item_id=:id AND ordinal=:o",Map.of("id",unit.itemId(),"o",unit.ordinal()),Long.class);
        var item=context.getBean(com.example.marketplace.order.api.OrderQueries.class).detail(f.parties().buyer().order().orderNumber(),shipmentAuthority(f.parties().buyer())).stores().stream().flatMap(s->s.items().stream()).filter(i->i.id().equals(unit.itemId())).findFirst().orElseThrow();long fee=item.returnPolicy().checkedAmount();
        assertEquals(Long.toString(net),quote.path("net").asText());assertEquals(Long.toString(fee),quote.path("increment").asText());assertEquals(Long.toString(Math.max(0,net-fee)),quote.path("refund").asText());assertEquals(Long.toString(Math.max(0,fee-net)),quote.path("additionalDue").asText());
        assertEquals(before.get("inventory_balance"),returnApplicationParticipants().get("inventory_balance"));assertEquals(before.get("inventory_reservation"),returnApplicationParticipants().get("inventory_reservation"));assertEquals(before.get("order_unit_hold"),returnApplicationParticipants().get("order_unit_hold"));assertEquals(before.get("claim_return_request"),returnApplicationParticipants().get("claim_return_request"));assertEquals(before.get("payment_refund_budget"),returnApplicationParticipants().get("payment_refund_budget"));
        assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.payment_refund_attempt WHERE claim_id=:id",Map.of("id",f.accepted().returnId()),Integer.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_fee_assessment WHERE intent_id=:id",Map.of("id",f.accepted().returnId()),Integer.class));assertEquals(0L,jdbc.queryForObject("SELECT coalesce(sum(reserved_increment),0) FROM marketplace.claim_fee_bucket WHERE order_id=:id",Map.of("id",f.parties().buyer().order().id()),Long.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_fee_bucket WHERE order_id=:id AND(active_assessment_id IS NOT NULL OR assessed_total<>0)",Map.of("id",f.parties().buyer().order().id()),Integer.class));
    }

    @Test void returnBuyerConsentAtomicallyReservesBoundItemRefundAndReplays() throws Exception {
        var f=finalQuoteReturn("final-consent",false);String base="/api/orders/"+f.parties().buyer().order().orderNumber()+"/returns/"+f.accepted().returnId();
        var quoted=accountRequest(f.parties().buyer().browser(),"POST",base+"/quote",Map.of("expectedRevision",3),csrfToken(f.parties().buyer().browser()));assertEquals(200,quoted.statusCode(),"actual final quote prerequisite: "+quoted.body());var quote=authMapper.readTree(quoted.body()).path("feeQuote");
        assertEquals("SELLER",quote.path("units").get(0).path("responsibility").asText());assertEquals("0",quote.path("increment").asText());assertEquals(quote.path("net").asText(),quote.path("refund").asText());assertEquals("0",quote.path("additionalDue").asText());
        var command=Map.of("key","buyer-final-consent","expectedRevision",3,"quoteId",quote.path("id").asText(),"quoteFingerprint",quote.path("fingerprint").asText(),"consent",true,"legacyConsent",false);var before=returnApplicationParticipants();
        var response=accountRequest(f.parties().buyer().browser(),"POST",base+"/consent",command,csrfToken(f.parties().buyer().browser()));assertEquals(202,response.statusCode(),"current buyer consent must reserve/bind exactly the inspected ITEM refund: "+response.body());
        var body=authMapper.readTree(response.body());assertEquals("REFUND_PENDING",body.path("progress").path("state").asText());assertEquals(4,body.path("progress").path("version").asLong());assertEquals("REQUESTED",body.path("progress").path("accepted").path("state").asText());UUID assessment=UUID.fromString(body.path("assessmentId").asText()),attempt=UUID.fromString(body.path("refundAttemptId").asText());
        var actual=new TransactionTemplate(transactionManager).execute(t->context.getBean(com.example.marketplace.payment.api.Refunds.class).get(attempt));assertEquals(f.accepted().returnId(),actual.claimId());assertEquals("ITEM",actual.purpose());assertEquals("RESERVED",actual.state());assertEquals(Long.parseLong(quote.path("refund").asText()),actual.amount());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_fee_binding WHERE assessment_id=:id AND attempt_id=:attempt",Map.of("id",assessment,"attempt",attempt),Integer.class));assertEquals("BOUND",jdbc.queryForObject("SELECT state FROM marketplace.claim_fee_assessment WHERE id=:id",Map.of("id",assessment),String.class));
        assertEquals(before.get("inventory_balance"),returnApplicationParticipants().get("inventory_balance"));assertEquals(before.get("inventory_reservation"),returnApplicationParticipants().get("inventory_reservation"));assertEquals("ACTIVE",jdbc.queryForObject("SELECT state FROM marketplace.order_unit_hold WHERE id=:id",Map.of("id",f.accepted().holdId()),String.class));assertEquals("PAID",orders().find(f.parties().buyer().order().orderNumber()).state());
        var stable=returnApplicationParticipants();assertEquals(response.body(),accountRequest(f.parties().buyer().browser(),"POST",base+"/consent",command,csrfToken(f.parties().buyer().browser())).body());assertEquals(stable,returnApplicationParticipants());
    }

    @Test void returnFinalConsentRejectsStaleTermsNonOwnersAndTrustedOverrides() throws Exception {
        var f=finalQuoteReturn("consent-private",true);var other=finalQuoteReturn("consent-foreign",false);var api=context.getBean(com.example.marketplace.claim.api.ReturnFinances.class);String number=f.parties().buyer().order().orderNumber();var owner=shipmentAuthority(f.parties().buyer());var quote=api.quote(number,f.accepted().returnId(),owner,3).feeQuote();var foreign=api.quote(other.parties().buyer().order().orderNumber(),other.accepted().returnId(),shipmentAuthority(other.parties().buyer()),3).feeQuote();
        var command=new com.example.marketplace.claim.api.ReturnFinances.Consent("explicit-consent",3L,quote.id(),quote.fingerprint(),true,false);String path="/api/orders/"+number+"/returns/"+f.accepted().returnId()+"/consent";var body=new java.util.HashMap<String,Object>(Map.of("key",command.key(),"expectedRevision",3,"quoteId",quote.id(),"quoteFingerprint",quote.fingerprint(),"consent",true,"legacyConsent",false));var before=returnApplicationParticipants();
        for(var browser:List.of(f.parties().seller().browser(),other.parties().buyer().browser(),authBrowser())) { assertEquals(404,accountRequest(browser,"POST",path,body,csrfToken(browser)).statusCode());assertEquals(before,returnApplicationParticipants()); }
        assertEquals(403,accountRequest(f.parties().buyer().browser(),"POST",path,body,null).statusCode());assertEquals(before,returnApplicationParticipants());
        for(String field:List.of("amount","full","worker","assessmentId","responsibility")) { var invalid=new java.util.HashMap<String,Object>(body);invalid.put(field,true);assertEquals(400,accountRequest(f.parties().buyer().browser(),"POST",path,invalid,csrfToken(f.parties().buyer().browser())).statusCode());assertEquals(before,returnApplicationParticipants()); }
        var denied=new java.util.HashMap<String,Object>(body);denied.put("consent",false);assertEquals(400,accountRequest(f.parties().buyer().browser(),"POST",path,denied,csrfToken(f.parties().buyer().browser())).statusCode());assertEquals(before,returnApplicationParticipants());
        for(var changed:List.of(new com.example.marketplace.claim.api.ReturnFinances.Consent(command.key(),2L,quote.id(),quote.fingerprint(),true,false),new com.example.marketplace.claim.api.ReturnFinances.Consent(command.key(),3L,quote.id(),"0".repeat(64),true,false),new com.example.marketplace.claim.api.ReturnFinances.Consent(command.key(),3L,quote.id(),quote.fingerprint(),true,true))) { assertEquals(409,assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->api.consent(number,f.accepted().returnId(),owner,changed)).status());assertEquals(before,returnApplicationParticipants()); }
        assertEquals(404,assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->api.consent(number,f.accepted().returnId(),owner,new com.example.marketplace.claim.api.ReturnFinances.Consent(command.key(),3L,foreign.id(),foreign.fingerprint(),true,false))).status());assertEquals(before,returnApplicationParticipants());
        var result=api.consent(number,f.accepted().returnId(),owner,command);assertEquals("REFUND_PENDING",result.progress().state());var stable=returnApplicationParticipants();assertEquals(result,api.consent(number,f.accepted().returnId(),owner,command));assertEquals(stable,returnApplicationParticipants());
        assertEquals(409,assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->new TransactionTemplate(transactionManager).execute(t->context.getBean(com.example.marketplace.claim.api.ReturnFees.class).withdraw(number,owner,result.assessmentId()))).status());assertEquals(stable,returnApplicationParticipants(),"physical received return cannot be abandoned through common financial withdrawal");
    }

    @Test void returnFinalConsentRollsBackAllFinancialAndHistorySqlStages() throws Exception {
        var f=finalQuoteReturn("consent-rollback",true);var api=context.getBean(com.example.marketplace.claim.api.ReturnFinances.class);String number=f.parties().buyer().order().orderNumber();var owner=shipmentAuthority(f.parties().buyer());var quote=api.quote(number,f.accepted().returnId(),owner,3).feeQuote();var command=new com.example.marketplace.claim.api.ReturnFinances.Consent("atomic-consent",3L,quote.id(),quote.fingerprint(),true,false);var before=returnApplicationParticipants();
        var stages=List.of("claim_fee_assessment","claim_fee_consent","claim_fee_bucket","claim_fee_assessment_bucket","claim_fee_assessment_unit","claim_fee_event","payment_refund_budget","payment_refund_attempt","payment_refund_event","claim_financial_refund_binding","claim_fee_binding_history","claim_fee_binding","claim_return_request","claim_return_history","claim_return_command","claim_return_financial_consent","job","outbox_event");
        for(String table:stages) {
            jdbc.getJdbcTemplate().execute("CREATE FUNCTION marketplace.d_consent_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'ACTUAL_CONSENT_"+table+"' USING ERRCODE='23514';END $$");jdbc.getJdbcTemplate().execute("CREATE TRIGGER d_consent_reject BEFORE "+(List.of("claim_fee_bucket","claim_return_request").contains(table)?"UPDATE":"INSERT")+" ON marketplace."+table+" FOR EACH ROW EXECUTE FUNCTION marketplace.d_consent_failure()");
            try { var error=assertThrows(RuntimeException.class,()->api.consent(number,f.accepted().returnId(),owner,command));Throwable root=error;while(root.getCause()!=null) { root=root.getCause(); }assertTrue(root instanceof java.sql.SQLException);assertEquals("23514",((java.sql.SQLException)root).getSQLState());assertTrue(root.getMessage().contains("ACTUAL_CONSENT_"+table),root.toString());assertEquals(before,returnApplicationParticipants(),"full atomic rollback at "+table); }
            finally { jdbc.getJdbcTemplate().execute("DROP TRIGGER d_consent_reject ON marketplace."+table);jdbc.getJdbcTemplate().execute("DROP FUNCTION marketplace.d_consent_failure()"); }
        }
        var result=api.consent(number,f.accepted().returnId(),owner,command);assertEquals("REFUND_PENDING",result.progress().state());var stable=returnApplicationParticipants();assertEquals(result,api.consent(number,f.accepted().returnId(),owner,command));assertEquals(stable,returnApplicationParticipants());java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"return-consent-sql-rollback.json"),authMapper.writeValueAsString(Map.of("actualCheckpoints",stages,"allReached",true,"allParticipantsRolledBack",true,"resume",1,"replayEffects",0)));
    }

