            jdbc.getJdbcTemplate().execute("CREATE FUNCTION marketplace.d_skip_support_graph() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL;END $$");jdbc.getJdbcTemplate().execute("CREATE TRIGGER d_skip_support_graph BEFORE INSERT ON marketplace."+table+" FOR EACH ROW EXECUTE FUNCTION marketplace.d_skip_support_graph()");
